<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue';import {api} from '../api';import {useWorkspace,type WorkTab} from '../stores';import Modal from '../components/Modal.vue';import SupervisorEdit from './SupervisorEdit.vue';
const props=defineProps<{tab:WorkTab}>();const work=useWorkspace(),data=ref<any>(null),query=ref(''),storeQuery=ref(''),showResults=ref(false),error=ref(''),loading=ref(false),editing=ref<any>(null),discard=ref(false);
async function load(){if(loading.value)return;loading.value=true;error.value='';try{data.value=await api('supervisors');}catch(e){data.value=null;error.value=(e as Error).message;}finally{loading.value=false;}}
const people=computed(()=>{const map=new Map<string,any>();for(const u of data.value?.users||[])map.set(u.id,{...u,eligible:true});for(const a of data.value?.assignments||[])if(!map.has(a.user_id))map.set(a.user_id,{...a.user,id:a.user_id,eligible:false});return [...map.values()];});
const results=computed(()=>!query.value.trim()?[]:people.value.filter(u=>[u.full_name,u.email,u.employee_code,u.job_title].join(' ').toLowerCase().includes(query.value.trim().toLowerCase())).sort((a,b)=>(a.employee_code||a.full_name||'').localeCompare(b.employee_code||b.full_name||'')));
const overview=computed(()=>(data.value?.stores||[]).map((s:any)=>{
 const rows=(data.value.assignments||[]).filter((a:any)=>a.store_id===s.id&&['supervisor','area_manager'].includes(a.role_type));
 const direct=rows.filter((a:any)=>a.role_type==='supervisor'&&a.user?.job_title?.includes('督導'));
 return {...s,rows,managers:rows.filter((a:any)=>!direct.includes(a)),primary:direct.filter((a:any)=>a.is_primary),proxies:direct.filter((a:any)=>!a.is_primary)};
}).filter((s:any)=>s.rows.length&&[s.store_code,s.store_name,...s.rows.map((a:any)=>[a.user?.full_name,a.user?.employee_code].join(' '))].join(' ').toLowerCase().includes(storeQuery.value.trim().toLowerCase())).sort((a:any,b:any)=>a.store_code.localeCompare(b.store_code,'zh-Hant',{numeric:true})));
function edit(u:any,roleType='supervisor'){props.tab.recordId=u.id;props.tab.payload={roleType};editing.value=u;query.value='';showResults.value=false;}
function leaveSearch(event:FocusEvent){if(!(event.currentTarget as HTMLElement).contains(event.relatedTarget as Node|null))showResults.value=false;}
function close(){if(props.tab.busy)return;if(props.tab.dirty){discard.value=true;return;}editing.value=null;}
function abandon(){props.tab.dirty=false;discard.value=false;editing.value=null;}
onMounted(load);watch(()=>work.active,id=>{if(id===props.tab.id)load();});
</script>
<template>
<header class="page-heading"><div><p class="eyebrow">組織與門市 / 經理與督導</p><h1>經理／督導管理</h1><p class="muted">搜尋人員指派門市；同店有多位督導時，指定一位主責，其餘為代理。</p></div><button :disabled="loading" @click="load">重新整理</button></header>
<p v-if="error" role="alert" class="notice error">{{error}}</p>
<div class="person-picker" @focusout="leaveSearch" @keydown.esc.stop.prevent="showResults=false"><label>搜尋經理／督導<input v-model="query" :disabled="loading||!data" placeholder="姓名、員編、職稱或電子郵件" autocomplete="off" @input="showResults=true" @focus="showResults=true"></label><div v-if="showResults&&query.trim()&&data" class="person-results" role="region" aria-label="人員搜尋結果"><div v-for="u in results" :key="u.id" class="person-option"><button :disabled="!data.canSupervisor" @click="edit(u)"><strong>{{u.full_name||u.email||'未命名'}}</strong><span>{{u.employee_code||'無員編'}} · {{u.job_title||'未提供職稱'}}</span><small v-if="!u.eligible">僅可解除既有指派</small></button><button v-if="data.canManager" class="secondary-role" @click="edit(u,'store_manager')">設定兼任店長</button></div><p v-if="!results.length" role="status">沒有符合搜尋的人員</p></div></div>
<section aria-label="管理門市總覽"><h2>管理門市總覽</h2><label class="store-search">搜尋已指派門市<input v-model="storeQuery" placeholder="門市代號、名稱或管理人員"></label><p v-if="loading" role="status">載入管理門市…</p><template v-else-if="data"><p class="muted">{{overview.length}} 間門市 · 依門市代號升冪排列</p><div class="module-table"><table><thead><tr><th aria-sort="ascending">門市 ↑</th><th>經理／管理職</th><th>主責督導</th><th>代理督導</th></tr></thead><tbody><tr v-for="s in overview" :key="s.id"><td><strong>{{s.store_code}}</strong><br>{{s.store_name}}<small v-if="!s.eligible">停用／總部</small></td><td v-for="group in ['managers','primary','proxies']" :key="group"><ul v-if="s[group].length"><li v-for="a in s[group]" :key="a.id"><button v-if="data.canSupervisor&&a.role_type==='supervisor'" @click="edit(a.user||{id:a.user_id})">{{a.user?.full_name||'未命名'}}<small>{{a.user?.employee_code}}</small></button><span v-else>{{a.user?.full_name||'未命名'}}<small>{{a.user?.employee_code}}</small></span></li></ul><span v-else class="muted">{{group==='primary'?'尚未指派':'—'}}</span></td></tr><tr v-if="!overview.length"><td colspan="4">{{storeQuery?'沒有符合搜尋的門市':'尚無經理／督導門市指派'}}</td></tr></tbody></table></div></template></section>
<Modal v-if="editing" :title="'選擇管理門市 · '+(editing.full_name||editing.employee_code||'未命名')" :busy="tab.busy" @cancel="close"><SupervisorEdit :tab="tab" embedded @saved="load" @close="close" /></Modal>
<Modal v-if="discard" title="放棄尚未儲存的指派？" @cancel="discard=false"><p>勾選與主責選擇尚未儲存，關閉會放棄這次修改。</p><div class="dialog-actions"><button @click="discard=false">繼續編輯</button><button class="danger" @click="abandon">放棄修改並關閉</button></div></Modal>
</template>
<style scoped>
.person-picker{position:relative;max-width:480px;margin-bottom:32px}.person-picker label,.store-search{display:grid;gap:8px;max-width:480px}.person-results{position:absolute;inset:100% 0 auto;z-index:5;max-height:300px;overflow:auto;background:var(--surface);border:1px solid var(--line);box-shadow:0 6px 16px #0002}.person-results p{padding:12px}.person-option{padding:8px;border-bottom:1px solid var(--line)}.person-option>button:first-child{display:flex;flex-direction:column;align-items:flex-start;gap:4px;width:100%;text-align:left;border:0;padding:10px;overflow-wrap:anywhere}.person-option button:hover,.person-option button:focus-visible{background:var(--soft)}.secondary-role{margin:4px 10px}.person-option span,small{color:var(--muted)}small{display:block;margin-top:4px}h2{font-size:18px}.module-table ul{list-style:none;margin:0;padding:0}.module-table li+li{margin-top:8px}.module-table button{text-align:left}.module-table table{min-width:0;table-layout:fixed}.module-table th,.module-table td{white-space:normal;overflow-wrap:anywhere}.module-table button{max-width:100%;white-space:normal;overflow-wrap:anywhere}@media(max-width:600px){.module-table th,.module-table td{padding:10px 4px;font-size:12px}.module-table button{padding:8px 4px;font-size:12px}}
</style>
